-- Đào tạo: bỏ cách xưng "chị/em" trên web (chị Hoa 02/11: web không xưng chị với em). Nội quy bỏ 2 dòng ghi chú riêng cho CEO và chữ "(bản nháp)"; sổ tay đổi "chị Hoa" thành "CEO".
UPDATE dt_doc SET body = ltrim(replace(replace(replace(replace(replace(body, '> Lưu ý cho chị Hoa: công ty từ 10 người trở lên phải có **Nội quy lao động** bằng văn bản đăng ký với Sở Lao động thì mới đủ căn cứ xử lý kỷ luật. Trang này là nội quy làm việc hằng ngày cho nhân viên đọc; bản đăng ký nên nhờ luật sư rà.' || char(10), ''), '> Lưu ý cho chị Hoa: công ty từ 10 người trở lên phải có **Nội quy lao động** bằng văn bản đăng ký với Sở Lao động thì mới đủ căn cứ xử lý kỷ luật. Trang này là nội quy làm việc hằng ngày cho nhân viên đọc; bản đăng ký nên nhờ luật sư rà.', ''), '> Bản nháp để chị Hoa sửa và duyệt. Giờ làm, chấm công, nghỉ phép lấy theo bản thảo "Quy chế chấm công và nghỉ phép" (ABOS-HR-QC-02) trên Drive. Chỗ nào chưa đúng thực tế thì sửa thẳng ở nút Sửa tài liệu.' || char(10), ''), '> Bản nháp để chị Hoa sửa và duyệt. Giờ làm, chấm công, nghỉ phép lấy theo bản thảo "Quy chế chấm công và nghỉ phép" (ABOS-HR-QC-02) trên Drive. Chỗ nào chưa đúng thực tế thì sửa thẳng ở nút Sửa tài liệu.', ''), char(10) || char(10) || char(10), char(10) || char(10)), char(10)), title = replace(title, ' (bản nháp)', '') WHERE id = 'dt-noi-quy';
UPDATE dt_doc SET body = replace(body, 'nhờ quản lý báo chị Hoa gắn tài khoản', 'nhờ quản lý báo CEO gắn tài khoản') WHERE id = 'dt-web-bat-dau';
UPDATE dt_doc SET body = replace(body, 'Tài liệu Chung (nội quy, quy chế) phải chị Hoa duyệt mới hiện.', 'Tài liệu do Lead / quản lý tạo hoặc sửa phải CEO duyệt mới hiện; trong lúc chờ, mọi người vẫn đọc bản đã duyệt.') WHERE id = 'dt-web-dao-tao';
UPDATE dt_doc SET body = replace(body, 'web tự báo đỏ cho quản lý và chị Hoa.', 'web tự báo đỏ cho quản lý và CEO.') WHERE id = 'dt-web-cong-viec';
